import re

NODE = re.compile(r'^#(?P<pre>[ |]*)@ (?P<type>\S+) \(id: (?P<id>\d+), line: (?P<line>\d+), location: (?P<loc>\([^)]*\)-\([^)]*\))\)(?P<star>\*)?\s*$')
ATTR = re.compile(r'^#(?P<pre>[ |]*)\+- (?P<field>[^:]+?):(?: (?P<value>.*?))?\s*$')
NULL = re.compile(r'^#(?P<pre>[ |]*)\(null node\)\s*$')
BANNER = re.compile(r'^##')

def parse(lines):
    nodes, attrs = [], []
    nlines, alines, skip = [], [], []
    owner = {}
    last_attr = {}
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if BANNER.match(ln):
            skip.append(i)
            continue
        m = NODE.match(ln)
        if m:
            pos = len(m.group('pre'))
            pa = last_attr.get(pos - 4)
            parent = owner.get(pos - 4, '') if pos >= 4 else ''
            owner[pos] = m.group('id')
            for k in [p for p in owner if p > pos]:
                del owner[k]
            for k in [p for p in last_attr if p >= pos]:
                del last_attr[k]
            nodes.append({'id': int(m.group('id')), 'type': m.group('type'), 'line': int(m.group('line')), 'location': m.group('loc'), 'newline': 'yes' if m.group('star') else 'no', 'depth': pos // 4, 'parent_id': parent, 'parent_field': pa['field'] if pa else ''})
            nlines.append(i)
            continue
        m = ATTR.match(ln)
        if m:
            pos = len(m.group('pre'))
            rec = {'node_id': owner.get(pos, ''), 'field': m.group('field').strip(), 'value': m.group('value') or ''}
            attrs.append(rec)
            last_attr[pos] = rec
            alines.append(i)
            continue
        m = NULL.match(ln)
        if m:
            pos = len(m.group('pre'))
            rec = last_attr.get(pos - 4)
            if rec is not None and not rec['value']:
                rec['value'] = '(null node)'
            alines.append(i)
            continue
    blocks = []
    if nodes:
        blocks.append({'name': 'nodes', 'kind': 'table', 'lines': nlines, 'records': nodes})
    if attrs:
        blocks.append({'name': 'attributes', 'kind': 'table', 'lines': alines, 'records': attrs})
    return {'blocks': blocks, 'skip': skip}
